func maxCount(daily []stats.DayCount) int64 {
	var max int64
	for _, day := range daily {
		if day.Count > max {
			max = day.Count
		}
	}
	return max
}

func barHeight(count, max int64) string {
	if max == 0 || count == 0 {
		return "height: 1px"
	}
	pct := count * 100 / max
	if pct < 3 {
		pct = 3
	}
	return "height: " + strconv.FormatInt(pct, 10) + "%"
}

